PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?breed ?purpose
WHERE {
  {
    dbr:Chongqing_dog dbp:kcStd ?std .
    FILTER(CONTAINS(str(?std), "hound"))
    BIND(dbr:Chongqing_dog AS ?breed)
    BIND("Hunting" AS ?purpose)
  } UNION {
    dbr:Kanni dbp:kcStd ?std .
    FILTER(CONTAINS(str(?std), "hound"))
    BIND(dbr:Kanni AS ?breed)
    BIND("Hunting" AS ?purpose)
  }
}
LIMIT 100

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?airport ?city ?distance
WHERE {
  {
    dbr:Chicago_Rockford_International_Airport dbo:city ?city .
    BIND("Chicago Rockford International Airport" AS ?airport) .
    BIND(0 AS ?distance) .
  }
  UNION
  {
    dbr:McClellan–Palomar_Airport dbo:city ?city .
    BIND("McClellan–Palomar Airport" AS ?airport) .
    BIND(0 AS ?distance) .
  }
}
LIMIT 100

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?birthDate 
WHERE {
  {
    <http://dbpedia.org/resource/Tom_Baker_(American_actor)> dbo:birthDate ?birthDate .
  }
  UNION
  {
    ?company dbo:president <http://dbpedia.org/resource/Dana_Brunetti> .
    ?company dbo:founder ?person .
    ?person dbo:birthDate ?birthDate .
    FILTER (?person = dbr:Anthony_Kimmins)
  }
}
LIMIT 100

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?property ?sum41Value ?passionPitValue
WHERE {
  { <http://dbpedia.org/resource/Sum_41> ?property ?sum41Value }
  { <http://dbpedia.org/resource/Passion_Pit> ?property ?passionPitValue }
  FILTER (?sum41Value = ?passionPitValue)
}
LIMIT 100

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?job 
WHERE {
  { dbr:Alexander_Acosta dbp:as ?job . }
  UNION
  { dbr:Edward_Columbus_Hosford dbp:wordnet_type ?job . }
}
LIMIT 100

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?group ?member
WHERE {
  { dbr:DC_Talk dbo:formerBandMember ?member . BIND(dbr:DC_Talk AS ?group) }
  UNION
  { dbr:Manchester_Orchestra dbo:bandMember ?member . BIND(dbr:Manchester_Orchestra AS ?group) }
}
LIMIT 100

