PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?writer ?skill 
WHERE {
  {
    dbr:Langston_Hughes dbo:occupation ?occupation .
    ?occupation rdfs:label ?skill .
    BIND(dbr:Langston_Hughes AS ?writer)
  }
  UNION
  {
    dbr:Ian_McEwan dbo:occupation ?occupation .
    ?occupation rdfs:label ?skill .
    BIND(dbr:Ian_McEwan AS ?writer)
  }
}
LIMIT 100
